// Get the output from Confidence Calculator
let data = $input.first().json;

// Check if wrapped in "output" and unwrap
if (data.output) {
  data = data.output;
}

// Ensure all required fields exist
const result = {
  confidenceLevel: data.confidenceLevel || 'UNKNOWN',
  confidenceScore: data.confidenceScore || 0.5,
  reasoning: data.reasoning || '',
  query: data.query || '',
  response: data.response || '',
  references: data.references || []
};

return {
  json: result
};

