// Get all Sheets rows
const sheetRows = $input.all();

// ===== CHECK FOR EMPTY HISTORY (includes empty objects!) =====
// Google Sheets returns [{}] when no results, not []
if (sheetRows.length === 0 || 
    !sheetRows[0]?.json || 
    Object.keys(sheetRows[0].json).length === 0) {

  return { 
    json: { 
      conversationHistory: '', 
      messageCount: 0,
      lastEscalated: false
    } 
  };
}

// ===== FILTER OUT EMPTY OBJECTS (double safety) =====
const validRows = sheetRows.filter(row => 
  row.json && Object.keys(row.json).length > 0
);

if (validRows.length === 0) {
  return { 
    json: { 
      conversationHistory: '', 
      messageCount: 0,
      lastEscalated: false
    } 
  };
}

// ===== SORT CHRONOLOGICALLY (oldest first) =====
const sortedRows = validRows.sort((a, b) => {
  const timeA = new Date(a.json.timestampReceived || a.json.timestampStart || 0);
  const timeB = new Date(b.json.timestampReceived || b.json.timestampStart || 0);
  return timeA.getTime() - timeB.getTime();
});

// ===== BUILD CONVERSATION HISTORY =====
let conversationHistory = '';
let messageIndex = 1;

sortedRows.forEach((row) => {
  const data = row.json;

  const senderEmail = data.senderEmail || 'Unknown';

  const userTimestamp = data.timestampReceived || data.timestampStart || new Date().toISOString();
  const aiTimestamp = data.timestampEnd || new Date().toISOString();

  const userDate = new Date(userTimestamp);
  const aiDate = new Date(aiTimestamp);

  const userDateStr = isNaN(userDate.getTime()) ? 'Date unavailable' : userDate.toLocaleString();
  const aiDateStr = isNaN(aiDate.getTime()) ? 'Date unavailable' : aiDate.toLocaleString();

  // User message
  conversationHistory += `[Message ${messageIndex}]
From: ${senderEmail}
Date: ${userDateStr}
Content: ${data.query || '[No content]'}

---

`;
  messageIndex++;

  // AI response
conversationHistory += `[Message ${messageIndex}]
From: AI Customer Support Team
Date: ${aiDateStr}
Content: ${data.response || '[No response]'}

---

`;
  messageIndex++;
});

// ===== CLEAN UP =====
conversationHistory = conversationHistory.trim();
if (conversationHistory.endsWith('---')) {
  conversationHistory = conversationHistory.slice(0, -3).trim();
}

// ===== GET LAST ESCALATED =====
const lastRow = sortedRows[sortedRows.length - 1]?.json || {};
const lastEscalated = lastRow.isEscalated || false;

// ===== RETURN DATA =====
return {
  json: {
    conversationHistory: conversationHistory,
    messageCount: sortedRows.length * 2,
    lastEscalated: lastEscalated
  }
};

// ===== GET THREAD DATA =====
const threadData = $('Get a thread').first().json;
const threadMessages = threadData.messages || [];

// AI email for filtering
const AI_EMAIL = 'YOUR_AI_EMAIL@example.com';

// ===== FILTER TO GET ONLY USER MESSAGES =====
const userMessages = threadMessages.filter(msg => {
  const msgFrom = msg.From || '';
  const emailMatch = msgFrom.match(/<([^>]+)>/);
  const msgSenderEmail = emailMatch ? emailMatch[1] : msgFrom;

  return msgSenderEmail.toLowerCase() !== AI_EMAIL.toLowerCase();
});

// Sort USER messages by date (oldest to newest)
const sortedUserMessages = userMessages.sort((a, b) => {
  return parseInt(a.internalDate) - parseInt(b.internalDate);
});

// Safety check
if (sortedUserMessages.length === 0) {
  throw new Error('No user messages found in thread');
}

// ===== GET CURRENT (LAST) USER MESSAGE =====
const lastUserMessage = sortedUserMessages[sortedUserMessages.length - 1];

// Extract sender info from FIRST user message
const fromField = userMessages[0].From;
const emailMatch = fromField.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1] : fromField;
const subject = userMessages[0].Subject;

// ===== CLEAN MESSAGE BODY (remove quoted text) =====
let chatInput = lastUserMessage.snippet || '';

// Remove quoted text patterns
chatInput = chatInput.split(/On\s+\w+,\s+\d+\s+\w+\s+\d+\s+at\s+\d+:\d+/i)[0].trim();

if (chatInput.includes('wrote:')) {
  chatInput = chatInput.split('wrote:')[0].trim();
}

// Remove lines starting with ">"
chatInput = chatInput
  .split('\n')
  .filter(line => !line.trim().startsWith('>'))
  .join('\n')
  .trim();

// Remove HTML entities
chatInput = chatInput
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"');

// ===== GET DATA FROM SHEETS HISTORY NODE =====
const sheetsHistory = $('Format Conversation History from Sheets').first().json;

// Extract values from Sheets
const conversationHistory = sheetsHistory.conversationHistory || '';
const previousMessageCount = sheetsHistory.messageCount || 0; // Previous messages
const isEscalated = sheetsHistory.lastEscalated || false; // Renamed for clarity

// Calculate current state
const isFirstMessage = previousMessageCount === 0; // True if no previous messages
const messageCount = 1; // Always 1 - representing current user message

// ===== RETURN DATA =====
return {
  json: {
    // ===== Thread Identifiers =====
    threadId: threadData.id,
    messageId: lastUserMessage.id,

    // ===== Current Message (from Gmail) =====
    chatInput: chatInput,
    subject: subject,
    senderEmail: senderEmail,

    // ===== Conversation Context (from Sheets) =====
    conversationHistory: conversationHistory,

    // ===== Message Metadata =====
    messageCount: messageCount, // Current message count = 1
    isFirstMessage: isFirstMessage, // True if previousMessageCount === 0
    isEscalated: isEscalated, // Previous escalation status

    // ===== Timestamps =====
    startTime: new Date().toISOString(), // When workflow started
    receivedTime: new Date(parseInt(lastUserMessage.internalDate)).toISOString(), // When user sent email

    // ===== Channel =====
    channel: 'email'
  }
};

const rows = $input.all();

// Google Sheets returns [{}] on no match (confirmed in existing Format Conversation History code)
const validRows = rows.filter(row =>
  row.json && Object.keys(row.json).length > 0
);

const isReEscalation = validRows.some(row => {
  const isEsc = String(row.json.isEscalated ?? '').toLowerCase();
  const response = String(row.json.response ?? '').toLowerCase();
  return (isEsc === 'true') && response === 'pending';
});

return { json: { isReEscalation } };

const data = $input.first().json;
const emailBody = (data.chatInput || '').toLowerCase();

const priorityKeywords = [
  "refund", "cancel", "cancellation", "speak to human",
  "human agent", "lawyer", "legal action", "unacceptable",
  "account number", "fraud", "chargeback", "compensation"
];

const frustrationIndicators = [
  "frustrated", "angry", "disgusted", "worst", "terrible",
  "awful", "ridiculous", "never again", "disappointed",
  "outraged", "furious"
];

const detectedPriority = priorityKeywords.filter(kw => emailBody.includes(kw));
const detectedFrustration = frustrationIndicators.filter(kw => emailBody.includes(kw));

const hasPriorityKeyword = detectedPriority.length > 0;
const hasNegativeSentiment = detectedFrustration.length > 0;

return [{
  json: {
    ...data,
    hasPriorityKeyword,
    hasNegativeSentiment,
    detectedKeywords: [...detectedPriority, ...detectedFrustration],
    escalationFlag: hasPriorityKeyword || hasNegativeSentiment,
    originalEmailContent: data.chatInput || ''
  }
}];
